// Só segue se o push foi na main E mexeu no texto do artigo.
// Sem este filtro, todo commit do projeto viraria um rascunho novo.
const body = $input.first().json.body ?? $input.first().json;

if (body.ref !== 'refs/heads/main') return [];

const touched = (body.commits ?? []).flatMap((c) => [
  ...(c.added ?? []), ...(c.modified ?? [])
]);

const article = touched.find((p) => p.startsWith('content/medium/') && p.endsWith('.md'));
if (!article) return [];

return [{ json: { path: article, sha: body.after } }];

// O H1 do arquivo vira o título do post; o resto vira o corpo.
// Repetir o título dentro do conteúdo faz o Medium mostrar dois títulos.
const md = $input.first().json.data ?? '';
const lines = md.split('\n');

const h1 = lines.findIndex((l) => l.startsWith('# '));
const title = h1 >= 0 ? lines[h1].replace(/^#\s+/, '').trim() : 'TicketFlow';
const content = (h1 >= 0 ? lines.slice(h1 + 1) : lines).join('\n').trim();

return [{ json: {
  title,
  contentFormat: 'markdown',
  content,
  publishStatus: 'draft',
  tags: ['software-architecture', 'microservices', 'kafka', 'java', 'distributed-systems'],
  canonicalUrl: 'https://github.com/patrickpriebe/ticketflow'
} }];
